__global__ void bias_add_kernel(float* __restrict__ out, const float* __restrict__ bias, int M, int N) {
    int col = blockIdx.x * blockDim.x + threadIdx.x;
    int row = blockIdx.y * blockDim.y + threadIdx.y;
