// Computes out = x @ weight^T + bias
// x: [M, K], weight: [N, K] (nn.Linear stores as [out, in]), bias: [N]
// out: [M, N]
torch::Tensor linear_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(x.is_cuda() && weight.is_cuda() && bias.is_cuda(), "All inputs must be CUDA tensors");
    TORCH_CHECK(x.dtype() == torch::kFloat32, "x must be float32");
    TORCH_CHECK(weight.dtype() == torch::kFloat32, "weight must be float32");
    TORCH_CHECK(bias.dtype() == torch::kFloat32, "bias must be float32");
    TORCH_CHECK(x.is_contiguous() && weight.is_contiguous() && bias.is_contiguous(), "All inputs must be contiguous");
    TORCH_CHECK(x.dim() == 2 && weight.dim() == 2, "x and weight must be 2D");

    int64_t M = x.size(0);
    int64_t K = x.size(1);
    int64_t N = weight.size(0);
    TORCH_CHECK(weight.size(1) == K, "weight/x shape mismatch");
    TORCH_CHECK(bias.size(0) == N, "bias/weight shape mismatch");

    auto out = torch::empty({M, N}, x.options());

    // Use cuBLASLt: compute C = alpha * A * B^T + beta * C
    // A = x [M x K] row-major, B = weight [N x K] row-major
    // We want C = x @ weight^T = A * B^T
    // cuBLASLt uses column-major, so we compute C^T = B * A^T
    // i.e., transa=CUBLAS_OP_N for B (weight row-major = col-major transposed)
    //       transb=CUBLAS_OP_T for A (x row-major)
    // Result C is [M x N] row-major = [N x M] col-major

    cublasLtHandle_t ltHandle;
    cublasLtCreate(&ltHandle);

    cublasLtMatmulDesc_t operationDesc = nullptr;
    cublasLtMatrixLayout_t Adesc = nullptr, Bdesc = nullptr, Cdesc = nullptr;
    cublasLtMatmulPreference_t preference = nullptr;

    float alpha = 1.0f, beta = 0.0f;

