    cublasSetStream(handle, stream);

    // C = alpha * op(A) * op(B) + beta * C
    // We want out[M,N] = x[M,K] @ weight^T[K,N]
    // cuBLAS column-major: out^T[N,M] = weight[N,K] @ x^T[K,M]
    // => sgemm(N, N, N, K, M, alpha, weight_ptr, N, x_ptr, K, beta, out_ptr, N)
    // Wait: cublasSgemm(handle, transa, transb, m, n, k, alpha, A, lda, B, ldb, beta, C, ldc)
    // where C[m,n] = A[m,k]*B[k,n] (col-major)
    // We want out_col[N,M] = weight[N,K] * x_col[K,M]
    //   m=N, n=M, k=K
    //   A=weight (col-major N x K, lda=N), transa=CUBLAS_OP_N
    //   B=x (col-major K x M, ldb=K), transb=CUBLAS_OP_N
    //   C=out (col-major N x M, ldc=N)
    // But weight is row-major [N,K] => col-major it's [K,N], lda=K, so use transa=CUBLAS_OP_T
    // x is row-major [M,K] => col-major it's [K,M], ldb=K, so use transb=CUBLAS_OP_N
    // Then C_col[N,M] = weight_col^T[N,K] * x_col[K,M] = weight_row[N,K] * x_col[K,M]
    // C_col is [N,M] col-major = out_row [M,N] row-major. Correct!

    cublasSgemm(
