        CUBLAS_OP_T,    // transa: weight stored row-major [N,K], treat as col-major [K,N] then transpose -> [N,K]
        CUBLAS_OP_N,    // transb: x stored row-major [M,K], treat as col-major [K,M]
        (int)N,         // m
        (int)M,         // n
        (int)K,         // k
