        weight.data_ptr<float>(), (int)K,  // lda=K (weight row-major [N,K])
        x.data_ptr<float>(),      (int)K,  // ldb=K (x row-major [M,K])
        &beta,
        out.data_ptr<float>(),    (int)N   // ldc=N (out row-major [M,N] = col-major [N,M])
    );

    cublasDestroy(handle);
    cublasLtDestroy(ltHandle);

    // Add bias: out[i,j] += bias[j]
    dim3 block(32, 16);
    dim3 grid((N + block.x - 1) / block.x, (M + block.y - 1) / block.y);
    bias_add_kernel<<<grid, block, 0, stream>>>(out.data_ptr<float>(), bias.data_ptr<float>(), (int)M, (int)N);

    return out;
}
