// cuBLASLt handle and workspace, initialized once.
struct CublasLtState {
    cublasLtHandle_t handle;
    void* workspace;
    size_t workspace_size;
    CublasLtState() {
        cublasLtCreate(&handle);
        workspace_size = 32 * 1024 * 1024; // 32 MB workspace
        cudaMalloc(&workspace, workspace_size);
    }
    ~CublasLtState() {
        cudaFree(workspace);
        cublasLtDestroy(handle);
    }
};

static CublasLtState& get_cublaslt_state() {
    static CublasLtState state;
    return state;
}

torch::Tensor linear_double_mish_cuda(torch::Tensor x, torch::Tensor weight, torch::Tensor bias) {
    TORCH_CHECK(x.is_cuda() && x.dtype() == torch::kFloat32, "x must be CUDA float32");
    TORCH_CHECK(weight.is_cuda() && weight.dtype() == torch::kFloat32, "weight must be CUDA float32");

    // x: [M, K], weight: [N, K] (nn.Linear convention), output: [M, N]
    auto x_contig = x.contiguous();
    auto w_contig = weight.contiguous();

    int M = x_contig.size(0);
    int K = x_contig.size(1);
    int N = w_contig.size(0);

    auto out = torch::empty({M, N}, x_contig.options());

    CublasLtState& st = get_cublaslt_state();

    cublasLtMatmulDesc_t opDesc;
    cublasLtMatrixLayout_t Adesc, Bdesc, Cdesc;

    cublasLtMatmulDescCreate(&opDesc, CUBLAS_COMPUTE_32F, CUDA_R_32F);

    // We want: out = x * weight^T
    // A = x [M,K] row-major => transa = CUBLAS_OP_N
    // B = weight [N,K] row-major, need weight^T so transb = CUBLAS_OP_T
    cublasOperation_t transA = CUBLAS_OP_N;
    cublasOperation_t transB = CUBLAS_OP_T;
    cublasLtMatmulDescSetAttribute(opDesc, CUBLASLT_MATMUL_DESC_TRANSA, &transA, sizeof(transA));
    cublasLtMatmulDescSetAttribute(opDesc, CUBLASLT_MATMUL_DESC_TRANSB, &transB, sizeof(transB));

    // Matrix layouts: row-major stored as col-major with swapped dims
    // A_cublaslt: M x K, leading dim K
    cublasLtMatrixLayoutCreate(&Adesc, CUDA_R_32F, M, K, K);
    // B_cublaslt: N x K, leading dim K (for transB=T, cublasLt sees K x N effectively)
    cublasLtMatrixLayoutCreate(&Bdesc, CUDA_R_32F, N, K, K);
    // C_cublaslt: M x N, leading dim N
    cublasLtMatrixLayoutCreate(&Cdesc, CUDA_R_32F, M, N, N);

    // Algorithm search
    cublasLtMatmulPreference_t pref;
    cublasLtMatmulPreferenceCreate(&pref);
    cublasLtMatmulPreferenceSetAttribute(pref, CUBLASLT_MATMUL_PREF_MAX_WORKSPACE_BYTES,
                                         &st.workspace_size, sizeof(st.workspace_size));

    cublasLtMatmulHeuristicResult_t heuristicResult;
    int returnedResults = 0;
    cublasLtMatmulAlgoGetHeuristic(st.handle, opDesc, Adesc, Bdesc, Cdesc, Cdesc,
                                    pref, 1, &heuristicResult, &returnedResults);

    float alpha = 1.0f, beta = 0.0f;

    if (returnedResults > 0) {
        cublasLtMatmul(st.handle, opDesc,
                       &alpha,
                       x_contig.data_ptr<float>(), Adesc,
                       w_contig.data_ptr<float>(), Bdesc,
                       &beta,
                       out.data_ptr<float>(), Cdesc,
                       out.data_ptr<float>(), Cdesc,
                       &heuristicResult.algo,
                       st.workspace, st.workspace_size,
                       0);
    } else {
        // Fallback: no algo found, use plain matmul
        cublasLtMatmul(st.handle, opDesc,
                       &alpha,
                       x_contig.data_ptr<float>(), Adesc,
                       w_contig.data_ptr<float>(), Bdesc,
                       &beta,
                       out.data_ptr<float>(), Cdesc,
                       out.data_ptr<float>(), Cdesc,
                       nullptr,
                       st.workspace, st.workspace_size,
                       0);
    }

    cublasLtMatmulPreferenceDestroy(pref);
    cublasLtMatrixLayoutDestroy(Adesc);
    cublasLtMatrixLayoutDestroy(Bdesc);
    cublasLtMatrixLayoutDestroy(Cdesc);
    cublasLtMatmulDescDestroy(opDesc);

    // Add bias if present
    if (bias.defined() && bias.numel() > 0) {
        out.add_(bias);
    }

    // Apply fused double Mish in-place
    run_double_mish_inplace(out.data_ptr<float>(), out.numel());

    return out;
}
